{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        "Treat E0001, E0002, E0010, and E0015 as baseline or diplomatic context, not as proof of prudent 2022 nuclear conduct.",
        "Do not double-count the same invasion, alert, and annexation episodes across Reuters, TASS, Interfax, UN, and IAEA source families."
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 evidence on command-and-control discipline, custody, safety procedures, and expert governance is thin.",
          "lenses": ["1B.3", "1B.7"],
          "best_source_or_query_direction": "Contemporaneous official decrees, appointments, defense/government records, IAEA/CTBTO material, and serious histories or inquiries on Russian nuclear command practice in 2022.",
          "why_it_matters": "Without this, the package is strong on escalation and rhetoric but weaker on whether internal safety management or expert institutions were strengthened or degraded."
        },
        {
          "gap": "Private crisis de-escalation and back-channel restraint are only lightly evidenced.",
          "lenses": ["1B.4", "1B.8"],
          "best_source_or_query_direction": "Contemporaneous official transcripts, treaty records, and serious diplomatic histories on 2022 nuclear-risk communications and crisis management.",
          "why_it_matters": "This is the main counterweight to the threat rhetoric and determines whether any limited restraint was actually ruler-attributed."
        }
      ],
      "reason": "The package fairly presents direct nuclear-risk escalation, coercive shielding, and arms-control deterioration, with contrary evidence preserved. It is usable, but the internal safety and expert-governance side is still too thin for high confidence."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        "Treat E0017, E0018, E0019, and E0023 as narrow, reactive, and mostly tactical negotiation or de-escalation evidence, not as durable peace leadership.",
        "Treat Reuters/Euronews/Investing/Yahoo/ThePrint rewrites of the same Feb. 24, Sept. 21, and Nov. 11 events as one source family each, not independent corroboration."
      ],
      "material_gaps": [
        {
          "gap": "Proxy restraint, ally control, and responsibility for foreseeable proxy conduct are only thinly documented.",
          "lenses": ["2B.5"],
          "best_source_or_query_direction": "UN/OSCE/ICRC material, court or inquiry records, and serious scholarship on Russian control over occupied-territory proxies and affiliated forces in 2022.",
          "why_it_matters": "This is needed to distinguish direct Russian aggression from the broader proxy environment and to avoid over- or under-attributing unlawful conduct."
        },
        {
          "gap": "The peace-talk window is documented, but the package does not fully establish whether credible peaceful alternatives were genuinely available on Russian terms.",
          "lenses": ["2B.1", "2B.7"],
          "best_source_or_query_direction": "Contemporaneous negotiation records, official diplomatic statements, and serious histories of the March 2022 talks and Istanbul channel.",
          "why_it_matters": "This determines whether the tactical pauses and negotiation references should count as real restraint or only battlefield repositioning."
        }
      ],
      "reason": "The package is strong on aggressive war initiation, civilian harm, annexation, and coercive escalation. The few de-escalatory items are properly labeled as limited and reactive."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        "Use E0042 as corroborative annual context, not as a standalone basis for severity.",
        "Avoid double-counting Amnesty, HRW, OVD-Info, and Meduza summaries for the same censorship and protest episodes."
      ],
      "material_gaps": [
        {
          "gap": "Direct ruler-level evidence on specific torture, prison abuse, or abuse-remedy failures is thin.",
          "lenses": ["3B.1", "3B.2", "3B.4"],
          "best_source_or_query_direction": "Court files, inquiry records, prison-monitoring reports, and serious investigative work on 2022 detention and torture cases in Russia.",
          "why_it_matters": "The package already shows systematic repression, but this would sharpen command attribution and remedy quality."
        },
        {
          "gap": "Federal versus regional attribution is not always explicit for every incident class.",
          "lenses": ["3B.2", "3B.9", "3B.10"],
          "best_source_or_query_direction": "Regional policing orders, ministry directives, and high-quality domestic monitoring on detention and protest suppression.",
          "why_it_matters": "This prevents over-attributing decentralized abuse while still capturing Putin-system responsibility where it is actually supported."
        }
      ],
      "reason": "The package can fairly present systematic domestic repression, censorship, protest suppression, and vulnerable-group targeting, with adequate adverse and contrary evidence. The main caution is attribution granularity, not absence of a coherent record."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [
        "Treat E0057 as inherited baseline context from 2020, not 2022 conduct.",
        "Treat EPDE, Golos, OVD-Info, Amnesty, and HRW as system-level evidence; do not multiply them as separate independent episodes when they describe the same narrowing of contestation."
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 evidence on practical court independence and elite contestation is thin.",
          "lenses": ["4B.4", "4B.8"],
          "best_source_or_query_direction": "Election-monitoring analyses, legal scholarship, constitutional or court records, and serious histories of the 2022 institutional environment.",
          "why_it_matters": "This would better separate formal legal control from actual ruler-attributed closure and help with the strength of the authoritarian-rigidity conclusion."
        },
        {
          "gap": "The package has strong evidence of narrowing but less on affirmative self-binding or protection of pluralism in 2022.",
          "lenses": ["4B.1", "4B.3"],
          "best_source_or_query_direction": "Contemporaneous evidence on opposition access, candidate registration, media licensing, and any real allowance of political challenge in 2022.",
          "why_it_matters": "This determines whether the record is just closed or actively anti-pluralist in target-period terms."
        }
      ],
      "reason": "The package fairly presents continued authoritarian closure, electoral narrowing, and suppression of scrutiny, with clear attribution to Putin's state apparatus. The main baseline issue is the 2020 term-reset, which should remain context only."
    },
    {
      "chapter_id": "5B",
      "decision": "pass",
      "remove_or_contextualize": [
        "Contextualize E0066, E0067, E0069, E0070, E0071, and E0072 as wartime fiscal and macro outcomes, not pure prosperity-policy successes or failures.",
        "Treat Reuters/Investing/Euronews/Yahoo repeats of the same macro stories as one source family and do not count them as separate corroboration."
      ],
      "material_gaps": [
        {
          "gap": "Distributional and household-level effects are still under-specified, especially by region, class, and welfare recipient group.",
          "lenses": ["5B.8", "5B.10"],
          "best_source_or_query_direction": "Rosstat microdata, household surveys, World Bank/IMF Russia-specific analysis, and serious academic work on 2022 Russian household welfare.",
          "why_it_matters": "This is necessary to separate broad macro stabilization from actual broad-based prosperity."
        },
        {
          "gap": "Productivity investment and implementation evidence is weaker than the evidence on wartime spending shifts.",
          "lenses": ["5B.6", "5B.7"],
          "best_source_or_query_direction": "Budget execution data, audits, sectoral reports, and independent analysis of education, health, infrastructure, and innovation spending in 2022.",
          "why_it_matters": "The chapter needs more than budget direction to judge whether the ruler advanced durable prosperity."
        }
      ],
      "reason": "The package can fairly present a mixed economic record: some competent crisis management and personnel choices, but also coercive wartime reallocation, inflation, income loss, and crowding out of civilian priorities. Attribution is plausible but should stay explicitly conditioned on sanctions, oil revenue, and central-bank independence."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        "Use UNICEF, WHO, and World Bank 2020-2021 material as baseline context only, not as direct 2022 ruler-performance evidence.",
        "Treat Rosstat revisions and 2023 retrospectives as outcome evidence with attribution caveats, not as clean proof of durable welfare improvement."
      ],
      "material_gaps": [
        {
          "gap": "Direct independent evidence on 2022 implementation and quality of housing, food security, healthcare, and education outcomes is thin.",
          "lenses": ["6B.2", "6B.5", "6B.6"],
          "best_source_or_query_direction": "UNICEF/WHO/UNDP/World Bank Russia-specific material, Russian household surveys, and independent monitoring of 2022 service delivery by domain.",
          "why_it_matters": "This is the main obstacle to distinguishing real welfare improvement from a mix of baseline indicators, crisis management, and official reporting."
        },
        {
          "gap": "The April 2022 support package needs more evidence on actual uptake, regional distribution, and exclusion.",
          "lenses": ["6B.3", "6B.8", "6B.10"],
          "best_source_or_query_direction": "Regional administrative data, beneficiary audits, and independent reporting on who received the support and who did not.",
          "why_it_matters": "Without this, the package leans too much on announced policy and aggregate outcomes instead of ruler-attributed lived welfare."
        }
      ],
      "reason": "The package is directionally usable but still too dependent on baseline dashboards, state revisions, and indirect attribution. A focused follow-up would materially improve fairness, especially on implementation and distribution."
    },
    {
      "chapter_id": "7B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        "Keep the Guardian/OCCRP LLCInvest item contextual unless paired with direct ownership or audited asset records.",
        "Do not collapse allegations, sanctions findings, and independent investigations into one evidentiary tier; keep the Treasury finding distinct from inferential media reporting."
      ],
      "material_gaps": [
        {
          "gap": "Direct public or audited proof of Putin's beneficial ownership remains limited.",
          "lenses": ["7B.3", "7B.4"],
          "best_source_or_query_direction": "Sanctions supporting dossiers, asset registries, court records, and investigative archives that tie specific assets or entities directly to Putin or his immediate network.",
          "why_it_matters": "This is the biggest gap between strong suspicion and fully explicit personal-nexus evidence."
        },
        {
          "gap": "The record on correction, promise-keeping, and ethical example is thinner than the record on deception and suppression.",
          "lenses": ["7B.1", "7B.2", "7B.8", "7B.10"],
          "best_source_or_query_direction": "Contemporaneous transcripts, fact-checks, and documented instances of retraction, correction, or commitment reversal by Putin in 2022.",
          "why_it_matters": "This would sharpen the balance between direct dishonesty evidence and any genuine countervailing candor or correction."
        }
      ],
      "reason": "The package does contain meaningful personal-nexus evidence, especially on deception, coercion against critics, and hidden asset networks. But the strongest self-dealing claims still rest partly on sanctions findings and inference, so a focused follow-up would materially improve confidence and attribution discipline."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [
        "Treat Reuters/Euronews/Investing/Yahoo/ThePrint rewrites of the same war-performance events as source-family duplicates.",
        "Keep the execution evidence separate from any moral evaluation of the invasion, repression, or nuclear threats in other chapters."
      ],
      "material_gaps": [
        {
          "gap": "Independent 2022 performance metrics for military, procurement, and industrial execution remain thin.",
          "lenses": ["8B.7", "8B.10"],
          "best_source_or_query_direction": "Russian budget-execution records, procurement data, military analyses, and serious histories of the 2022 campaign.",
          "why_it_matters": "This is needed to distinguish frantic adaptation from genuinely effective execution against the ruler's own program."
        },
        {
          "gap": "The dossier shows program declaration and wartime adaptation, but less clean evidence on sustained goal advancement before year-end.",
          "lenses": ["8B.8", "8B.9"],
          "best_source_or_query_direction": "Contemporaneous defense-industrial reporting, command-performance analysis, and Russian-language budget or logistics records.",
          "why_it_matters": "Without this, the package can show movement and adaptation, but not fully whether those moves translated into durable progress."
        }
      ],
      "reason": "The package fairly presents the program-to-action-to-outcome chain for 2022 wartime execution, including adaptation, personnel changes, and reverses. It is coherent so long as the evaluator keeps moral and competence judgments separate."
    }
  ]
}
